using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configure the LLM provider ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---

var noteTaker = new NoteTakingTool();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(noteTaker.AddNote),
    AIFunctionFactory.Create(noteTaker.GetNotes),
};

// --- Build the agent ---

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of quantum computing on cryptography";

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "researcher",
        Description = "A research agent that searches the web and takes notes to produce a summary.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = tools,
        },
    });

Console.WriteLine($"🔍 Researching: {topic}");
Console.WriteLine(new string('─', 60));

// --- Run the agent ---

var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(
    $"""
    Research the following topic thoroughly: "{topic}"

    Follow these steps:
    1. Search the web using multiple targeted queries to gather diverse information
    2. Take notes on the most important findings from each search
    3. After gathering enough information, retrieve all your notes
    4. Provide a comprehensive summary that synthesizes your research

    Be thorough but concise. Always use the tools available to you.
    """,
    session);

Console.WriteLine(response);
Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine("✅ Research complete.");

// =============================================================================
// Tool definitions
// =============================================================================

/// <summary>Simulates web search. Replace with a real search API for production use.</summary>
public static class WebSearchTool
{
    private static int s_searchCount;

    [Description("Search the web for information on a given query. Returns a list of relevant results with snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        s_searchCount++;
        Console.WriteLine($"  🌐 [{s_searchCount}] Searching: {query}");

        // Simulate network latency
        await Task.Delay(150);

        // In production, call Bing Search API, Google Custom Search, etc.
        return $"""
            Search results for "{query}":
            1. Wikipedia — Overview article covering the history, key concepts, and recent developments related to {query}.
            2. Nature (2025) — Peer-reviewed study finding significant advances in {query}, with implications for industry and academia.
            3. TechCrunch (2026) — Industry analysis reporting growing investment and adoption trends in {query}.
            4. IEEE Spectrum — Technical deep-dive explaining the underlying mechanisms and future outlook of {query}.
            5. arxiv.org (2026) — Preprint summarizing the latest breakthroughs and open challenges in {query}.
            """;
    }
}

/// <summary>Stores research notes in memory for the duration of the agent run.</summary>
public class NoteTakingTool
{
    private readonly List<string> _notes = [];

    [Description("Save a research note for later reference. Use this to record key findings.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved ({note.Length} chars)");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return string.Join("\n\n", _notes.Select((n, i) => $"--- Note #{i + 1} ---\n{n}"));
    }
}

